const PayloadSchemaJSON = "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"https://trusttasks.org/spec/hcp/entries/get/0.1\",\"title\":\"HCP — Get Entry — payload\",\"description\":\"The request payload of the HCP 2.0-draft-3 Get entry operation (HCP 5.2.2): an HCP Client asks a provider for one named entry, for a stated purpose, under the grant its access token evidences. The outer document members (id, type, issuer, recipient, issuedAt, expiresAt, proof) are owned by the framework — SPEC §6.3. Every maxLength, maxItems and maxProperties in this schema is a Trust Tasks framework bound (SPEC §7.3 item 19), not an HCP requirement; so is every minLength or minItems of 1 on a member HCP's own schema allows to be empty.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"purpose\",\"accessToken\"],\"properties\":{\"ref\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"HCP `ref`: the grant-scoped reference a Context Client was given when the entry was disclosed to it (HCP 5.2.2, 7.4). Exactly one of `ref` and `entryId` is present; that rule is not checked by the schema (a schema `oneOf` would complicate every generated library), and a request with both or neither fails with `malformedRequest`. The maxLength is a framework bound, not an HCP requirement.\"},\"entryId\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"HCP `entryId`: the entry's `id`, by which a Management Client names it (HCP 5.2.2). A Context Client never knows an entry's `id` (HCP 7.4).\"},\"purpose\":{\"$ref\":\"#/$defs/PurposeCode\",\"description\":\"HCP `purpose`: a purpose code the grant approved for a category of the entry (HCP 5.2.2, 6.1.5.2).\"},\"purposeDescription\":{\"type\":\"string\",\"maxLength\":1024,\"description\":\"HCP `purposeDescription`: a plain-language statement of the task, recorded in the provider's audit log (HCP 5.2.2, 8.2). The maxLength is a framework bound, not an HCP requirement.\"},\"version\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"HCP `version`: the entry version to return instead of the current one (HCP 5.2.2).\"},\"accessToken\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":8192,\"description\":\"The HCP access token for the grant under which the client acts (HCP 12, 13), carried unchanged. HCP's HTTP Binding sends it as a Bearer token (HCP 9.3); this member carries it in the document. The provider validates it exactly as over HTTP and treats it as opaque. The maxLength is a framework bound, not an HCP requirement.\"}},\"$defs\":{\"Urn\":{\"type\":\"string\",\"pattern\":\"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"description\":\"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers.\"},\"PurposeCode\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An HCP purpose code: an absolute URI naming the purpose for which context is requested or may be used (HCP 6.1.5.2).\"}}}"

// ResponsePayloadSchemaJSON is PayloadSchemaJSON for the success-response variant.
const ResponsePayloadSchemaJSON = "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$ref\":\"#/$defs/Response\",\"$defs\":{\"Response\":{\"$anchor\":\"response\",\"title\":\"HCP — Get Entry — response payload\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"entry\",\"retrievalId\",\"minimization\",\"directives\",\"respondedAt\"],\"description\":\"The HCP Get entry result (HCP 5.2.2): the entry, inside a result so that the minimization report has somewhere to sit. Failures use trust-task-error, not this shape.\",\"properties\":{\"entry\":{\"anyOf\":[{\"$ref\":\"#/$defs/Disclosure\"},{\"$ref\":\"#/$defs/Entry\"}],\"description\":\"HCP `entry`: a Disclosure where the requester is a Context Client (HCP 7.4), with its `useUntil` (HCP 7.6); otherwise the whole Entry.\"},\"retrievalId\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"HCP `retrievalId`: the `urn:uuid:` identifier of this retrieval, recorded in the `context.read` audit event (HCP 5.2.2, 8.2).\"},\"minimization\":{\"$ref\":\"#/$defs/MinimizationReport\",\"description\":\"HCP `minimization`: the minimization report (HCP 7.5). Its `method` is `none`, since the caller named a single entry (HCP 5.2.2, 9.4.2).\"},\"directives\":{\"type\":[\"array\",\"null\"],\"items\":{\"$ref\":\"#/$defs/Directive\"},\"description\":\"HCP `directives`: the directives that apply, where the requester is a Context Client (HCP 5.2.2, 6.4); empty when none applies. Null where the requester is not a Context Client, to whom HCP delivers no directives. HCP's own shape leaves the member optional; the carriage requires it, as a list or null, so that \\\"none applies\\\" is never confused with \\\"not a Context Client\\\", pending HCP confirmation (question 42).\"},\"respondedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"HCP `timestamp`, renamed: the date-time of the response (HCP 5.2.2).\"}}},\"Instant\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"An RFC 3339 instant.\"},\"Directive\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"directiveId\",\"action\",\"effect\",\"text\",\"setBy\",\"createdAt\"],\"description\":\"What a client may do with context it received, or on the Context Subject's behalf (HCP 6.4). A directive only narrows: it never authorizes a disclosure the grant does not. Where two that apply disagree, `deny` prevails over `ask-first`, and `ask-first` over `permit` (HCP 6.4).\",\"properties\":{\"directiveId\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"Stable for the life of the directive (HCP 6.4).\"},\"action\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^(share|sign|transact|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)$\",\"description\":\"What the directive governs: `share` (passing received context to another agent), `sign` (signing, agreeing to or committing to anything on the Context Subject's behalf), `transact` (spending, buying or entering a contract on their behalf), or an absolute URI naming another action (HCP 6.4, A.3). A client MUST NOT treat an action it does not recognize as a permission; it reads the directive from `text`. The pattern admits the slug or an absolute URI's outline only: it carries no `format: uri`, which would refuse every slug, so checking that a custom value is a well-formed absolute URI, as HCP's prose requires (HCP A.3), is the consumer's check.\"},\"effect\":{\"type\":\"string\",\"enum\":[\"deny\",\"ask-first\",\"permit\"],\"description\":\"`deny`: the client MUST NOT take the action. `ask-first`: the client MUST obtain the Context Subject's confirmation each time before taking it. `permit`: the client may take it without asking (HCP 6.4). HCP's own values, carried verbatim.\"},\"text\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":4096,\"description\":\"The directive in the Context Subject's words (HCP 6.4). A client presents it to a model as data, never as instructions (HCP 7.4). The maxLength is a framework bound, not an HCP requirement.\"},\"categories\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":256,\"items\":{\"$ref\":\"#/$defs/Category\"},\"description\":\"The categories whose context the directive governs; absent means every category, held now or later (HCP 6.4). The maxItems is a framework bound, not an HCP requirement.\"},\"operators\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":256,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048},\"description\":\"The Client Operators the directive applies to, each a DNS domain or an operator identifier, matched as for standing rules; absent means every operator (HCP 6.4, 6.3). The maxItems is a framework bound, not an HCP requirement.\"},\"setBy\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"Set by the provider: `context-subject`, or the `delegationId` of the delegate who set it (HCP 6.4, 6.3).\"},\"createdAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"Set by the provider: when the directive was set (HCP 6.4).\"}}},\"Category\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^([a-z][a-z0-9_]*|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)$\",\"description\":\"An HCP context category (HCP 4.5), the primary unit of access control: either a slug from HCP's category registry, such as `general_preferences` or `health_context`, or a custom category written as an absolute URI under a domain its definer controls. A custom category is not portable between providers without bilateral agreement (HCP 4.5). The pattern admits the slug or an absolute URI's outline only: it carries no `format: uri`, which would refuse every slug, so checking that a custom value is a well-formed absolute URI, as HCP's prose requires (HCP A.3), is the consumer's check.\"},\"Urn\":{\"type\":\"string\",\"pattern\":\"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"description\":\"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers.\"},\"MinimizationReport\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"method\"],\"description\":\"The minimization report a query or get-entry result carries (HCP 7.5). It MUST NOT carry the number of entries considered, the number available within scope, or any other measure of what was withheld (HCP 7.5); no schema can check that by name.\",\"properties\":{\"method\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256,\"description\":\"The relevance method that determined the final ordering (HCP 7.3): the method the provider declares as `minimization_method` in its discovery document (HCP 19.3), such as `lexical`, `semantic` or `llm`, or `none` for a get-entry result. The set of values is open.\"}}},\"Entry\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"schema\",\"id\",\"type\",\"subject\",\"content\",\"assertion\",\"classification\",\"record\"],\"description\":\"An HCP entry, in the one form a provider emits (HCP 4.2, 4.3). A Context Client never receives one: it receives a Disclosure instead (HCP 7.4). The whole entry, with its stable `id`, reaches only the Context Subject's own access (HCP 7.4).\",\"properties\":{\"@context\":{\"type\":[\"array\",\"string\"],\"description\":\"The entry's JSON-LD context, `https://hcp.example/contexts/v2` in HCP 2.0-draft-3 (HCP 4.2).\"},\"schema\":{\"type\":\"string\",\"const\":\"https://hcp.example/spec/entry/2.0\",\"description\":\"The version of the entry structure, compared as an exact string (HCP 4.2, 1.7). HCP 2.0-draft-3 defines this one value.\"},\"id\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"The entry's stable identifier, the same across all its versions (HCP 4.2). Never disclosed to a Context Client, which names the entry by a `ref` (HCP 7.4).\"},\"type\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256},\"minItems\":1,\"description\":\"The entry's types. It MUST include `ContextEntry` (HCP 4.2). That rule is stated here and not in the schema: the registry's Rust generator does not support `contains`, so a validator does not check it.\"},\"subject\":{\"$ref\":\"#/$defs/EntrySubject\",\"description\":\"The Context Subject the entry is about.\"},\"content\":{\"$ref\":\"#/$defs/Content\",\"description\":\"What is said about the Context Subject, shaped by its content profile (HCP 4.2).\"},\"assertion\":{\"$ref\":\"#/$defs/Assertion\",\"description\":\"What the submitting client states about the assertion (HCP 4.2, 4.4).\"},\"classification\":{\"$ref\":\"#/$defs/Classification\",\"description\":\"HCP's classification of the entry: its categories, dimension and purpose limits (HCP 4.2, 4.5).\"},\"evidence\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/EvidenceItem\"},\"description\":\"Evidence items (HCP 4.2.2): at most one whose `role` is `content`. Absent or empty when the entry carries none. This rule is stated here and not in the schema: the registry's Rust generator does not support `contains`, so a validator does not check it.\"},\"record\":{\"$ref\":\"#/$defs/Record\",\"description\":\"The provider's record of the entry: status, version, provenance, relationships, conversion and metadata (HCP 4.2).\"}}},\"Record\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"status\",\"version\",\"provenance\"],\"description\":\"The provider's record of the entry (HCP 4.2). Withheld from a Context Client in full (HCP 7.4).\",\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"active\",\"deprecated\",\"conflicted\",\"expired\",\"revoked\",\"suspended\",\"deleted\"],\"description\":\"The entry's lifecycle state (HCP 4.2.4). HCP's own values, carried verbatim.\"},\"version\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The revision number: starts at 1 and increments by exactly 1 on each revision (HCP 4.2).\"},\"provenance\":{\"$ref\":\"#/$defs/Provenance\",\"description\":\"Who asserted, submitted, authorized, recorded and confirmed this version (HCP 3.5–3.8).\"},\"relationships\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/Relationship\"},\"description\":\"Relationships to other entries (HCP 4.2.3). Absent or empty when there are none.\"},\"conversion\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"from\",\"convertedAt\",\"convertedBy\"],\"description\":\"Present only on an entry converted from HCP v1 (HCP 4.3).\",\"properties\":{\"from\":{\"type\":\"string\",\"maxLength\":2048,\"description\":\"What the entry was converted from.\"},\"convertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When it was converted.\"},\"convertedBy\":{\"type\":\"string\",\"maxLength\":2048,\"description\":\"Who converted it.\"},\"unmapped\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"v1 members the conversion did not map.\"}}},\"metadata\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"Free-form data the implementation attaches for its own purposes; carries no HCP meaning (HCP 4.2).\"}}},\"Relationship\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"type\",\"target\",\"assertedBy\",\"recordedAt\"],\"description\":\"A relationship from this entry to another (HCP 4.2.3). Only a `contradicts` relationship may carry a `proposal` (HCP 4.7.4), which is a `RecordedProposal`, as HCP defines it. This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"type\":{\"$ref\":\"#/$defs/RelationshipType\",\"description\":\"The kind of relationship.\"},\"target\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The related entry's `id`.\"},\"assertedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"role\",\"id\"],\"description\":\"Who asserted the relationship.\",\"properties\":{\"role\":{\"type\":\"string\",\"enum\":[\"management-client\",\"context-client\",\"authorization-service\",\"hcp-provider\"],\"description\":\"Their role (HCP 3.9). HCP's own values, carried verbatim.\"},\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"Their identifier.\"}}},\"recordedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded the relationship.\"},\"proposal\":{\"$ref\":\"#/$defs/RecordedProposal\",\"description\":\"A proposal for resolving a conflict, which changes nothing until the Context Subject acts (HCP 4.7.4).\"}}},\"RecordedProposal\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"act\",\"entry\",\"rationale\",\"weighed\",\"proposedBy\",\"proposedAt\"],\"description\":\"A proposal for resolving a conflict, as the provider records it on a `contradicts` relationship (HCP 4.7.4). It changes nothing until the Context Subject acts. It is the `Proposal` a client writes (entry-write.schema.json), with `proposedBy` and `proposedAt`, which the provider sets and never takes from a request (HCP 4.7.4). A proposal is never disclosed to a Context Client (HCP 7.4). Open, as HCP's own shape is.\",\"properties\":{\"act\":{\"type\":\"string\",\"enum\":[\"reject\",\"accept\",\"supersede\"],\"description\":\"The act proposed (HCP 4.7.3, 4.7.4). HCP's own values, carried verbatim.\"},\"entry\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The entry the act applies to (HCP 4.7.4). The maxLength is a framework bound, not an HCP requirement.\"},\"rationale\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":4096,\"description\":\"Why, in words the Context Subject can read (HCP 4.7.4). The maxLength is a framework bound, not an HCP requirement.\"},\"weighed\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":64,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048},\"description\":\"What the proposal considered: an open set, of which HCP defines `basis`, `declarationType`, `standing`, `permittedPurposes`, `recency` and `confidence` (HCP 4.7.4). The maxItems and maxLength are framework bounds, not HCP requirements.\"},\"proposedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"role\",\"id\"],\"description\":\"Who made the proposal: the provider under the Memory Manager Profile, or the client that asserted the conflict (HCP 4.7.4, 15). Set by the provider, never taken from a request.\",\"properties\":{\"role\":{\"type\":\"string\",\"enum\":[\"management-client\",\"context-client\",\"authorization-service\",\"hcp-provider\"],\"description\":\"Their role (HCP 3.9). HCP's own values, carried verbatim.\"},\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"Their identifier. The maxLength is a framework bound, not an HCP requirement.\"}}},\"proposedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded the proposal (HCP 4.7.4). Set by the provider, never taken from a request.\"}}},\"RelationshipType\":{\"type\":\"string\",\"enum\":[\"derivedFrom\",\"supersedes\",\"contradicts\",\"duplicates\"],\"description\":\"How one entry relates to another (HCP 4.2.3). HCP's own values, carried verbatim.\"},\"Provenance\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"assertedBy\",\"assertedAt\",\"source\",\"submittedByClient\",\"authorizedUnder\",\"recordedByProvider\",\"recordedAt\"],\"description\":\"The provenance of one version of an entry (HCP 4.2, 3.5).\",\"properties\":{\"assertedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\",\"assurance\"],\"description\":\"The Context Asserter (HCP 3.5, 3.6).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The Context Asserter's identifier.\"},\"assurance\":{\"$ref\":\"#/$defs/Assurance\",\"description\":\"How the asserter's identity was established.\"},\"via\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"kind\",\"id\"],\"description\":\"Present only where a client attested for an issuer under the issuer's authorization (HCP 3.7).\",\"properties\":{\"kind\":{\"type\":\"string\",\"enum\":[\"authorization-credential\",\"arrangement\"],\"description\":\"What the client attested under. HCP's own values, carried verbatim.\"},\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The identifier of the attestation authorization or the recorded arrangement.\"}}}}},\"assertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the assertion was made, as the submitting client states it.\"},\"source\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The origin of the entry, as the submitting client states it: a conversation or document identifier, `person-input` or `integration` (HCP 4.2).\"},\"submittedByClient\":{\"$ref\":\"#/$defs/ClientDescription\",\"description\":\"The HCP Client that submitted this version, and its Client Operator (HCP 3.5).\"},\"authorizedUnder\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The grant under which this version was written.\"},\"recordedByProvider\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The HCP Provider that recorded this version.\"},\"recordedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded this version.\"},\"confirmations\":{\"type\":\"array\",\"description\":\"Confirmation records for this version (HCP 3.8). Absent or empty when there are none.\",\"items\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"disposition\",\"confirmedBy\",\"confirmedAt\"],\"properties\":{\"disposition\":{\"type\":\"string\",\"enum\":[\"confirmed\",\"rejected\"],\"description\":\"Whether the Context Subject confirmed or rejected the version.\"},\"confirmedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\"],\"description\":\"Who confirmed or rejected it.\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"Their identifier.\"}}},\"confirmedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When.\"}}}}}},\"ClientDescription\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\",\"name\",\"operator\"],\"description\":\"An HCP Client and its Client Operator, as recorded (HCP 3.5, 3.2.8).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The client's identifier.\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The client's name.\"},\"operator\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\",\"name\"],\"description\":\"The Client Operator.\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The operator's identifier.\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The operator's name.\"}}}}},\"Assurance\":{\"type\":\"string\",\"enum\":[\"unverified\",\"authenticated\",\"cryptographically-verified\"],\"description\":\"How a Context Asserter's identity was established (HCP 3.6). HCP's own values, carried verbatim.\"},\"EvidenceItem\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"role\",\"type\"],\"description\":\"One evidence item (HCP 4.2.2). An item of a type the provider does not recognize is preserved and never raises assurance (HCP A.3). An item whose type is `verifiable-credential` MUST carry `credential`, an object with `@context`, `type`, `issuer` and `credentialSubject`, held whole as its issuer secured it (HCP 4.2.2). This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"role\":{\"type\":\"string\",\"enum\":[\"content\",\"supports\"],\"description\":\"`content`: the item's credential is the entry's content (VC Evidence Profile). `supports`: the item backs content stated elsewhere in the entry (HCP 4.2.2).\"},\"type\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The evidence type: `verifiable-credential`, or a URI (HCP 4.2.2, A.3).\"},\"credential\":{\"description\":\"The credential: for `verifiable-credential`, a W3C Verifiable Credential with `@context`, `type`, `issuer` and `credentialSubject`, whose own data model governs its contents (HCP 4.2.2, 14.2).\"},\"verification\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"result\",\"at\"],\"description\":\"The provider's record of its most recent verification of the credential (HCP 4.2.2). Set only by the provider.\",\"properties\":{\"result\":{\"type\":\"string\",\"enum\":[\"verified\",\"failed\"],\"description\":\"The outcome.\"},\"at\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider verified.\"},\"by\":{\"type\":\"string\",\"enum\":[\"provider\",\"trust-domain\"],\"description\":\"Who verified: the provider, or the Context Subject's trust domain under end-to-end encrypted storage (HCP 4.8). HCP's own values, carried verbatim.\"}}}}},\"Classification\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"categories\"],\"description\":\"HCP's classification of the entry (HCP 4.2, 4.5). A grant reaches an entry when it covers any one of the entry's categories (HCP 4.5).\",\"properties\":{\"categories\":{\"type\":\"array\",\"minItems\":1,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/Category\"},\"description\":\"One or more categories, without duplicates (HCP 4.2, 4.5). In a disclosure, only the categories the requesting grant covers (HCP 7.4).\"},\"dimension\":{\"type\":[\"string\",\"null\"],\"maxLength\":2048,\"description\":\"A free-form identifier of the dimension the entry addresses, scoped within its categories: a hint for conflict detection that grants and limits nothing (HCP 4.2).\"},\"permittedPurposes\":{\"type\":\"array\",\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/PurposeCode\"},\"description\":\"The Authorizing Principal's narrowing of the entry's purposes; absent means no limit (HCP 4.2.6).\"}}},\"PurposeCode\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An HCP purpose code: an absolute URI naming the purpose for which context is requested or may be used (HCP 6.1.5.2).\"},\"Assertion\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"declarationType\"],\"description\":\"What the submitting client states about the assertion (HCP 4.2). `confidence` is REQUIRED and non-null when `declarationType` is `model-inferred`, and null or absent otherwise (HCP 4.2, 4.4). This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"declarationType\":{\"type\":\"string\",\"enum\":[\"person-declared\",\"model-inferred\",\"issuer-attested\"],\"description\":\"What kind of party made the assertion (HCP 4.4); never omitted. HCP's own values, carried verbatim.\"},\"confidence\":{\"type\":[\"string\",\"null\"],\"enum\":[\"high\",\"medium\",\"low\",null],\"description\":\"How confident an inferring model is (HCP 4.2, 4.4).\"},\"validUntil\":{\"type\":[\"string\",\"null\"],\"format\":\"date-time\",\"description\":\"The instant after which the content no longer holds; absent or null means it does not expire (HCP 4.2). Not the instant after which a disclosed copy stops being usable, which is a disclosure's `useUntil` (HCP 7.6).\"},\"basis\":{\"$ref\":\"#/$defs/Basis\",\"description\":\"What the assertion was drawn from (HCP 4.2.5).\"},\"permittedPurposes\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/PurposeCode\"},\"description\":\"The purposes the asserter permits the entry to be used for; absent means no limit (HCP 4.2.6). The bound of 256 is a framework bound, not an HCP requirement.\"}}},\"Basis\":{\"type\":\"object\",\"additionalProperties\":true,\"description\":\"What an assertion was drawn from (HCP 4.2.5). It identifies no party but the Context Subject.\",\"properties\":{\"drawnFrom\":{\"type\":\"array\",\"maxItems\":256,\"items\":{\"type\":\"string\",\"maxLength\":2048},\"description\":\"The sources the assertion was drawn from. The bound of 256 is a framework bound, not an HCP requirement.\"},\"task\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"The task during which the assertion was made.\"},\"setting\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"The setting in which the assertion was made.\"},\"rationale\":{\"type\":\"string\",\"maxLength\":4096,\"description\":\"Why the asserter drew the conclusion.\"}}},\"Content\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"profile\"],\"description\":\"Entry content. `profile` names its shape (HCP 4.2). Under the General Context Profile it carries `value` and optionally `language` (HCP 11.2); under the VC Evidence Profile it carries `evidence`, the index of the evidence item holding the credential, and no `value` (HCP 4.2.2, 14). So `value` is REQUIRED under General Context, and under VC Evidence `evidence` is REQUIRED and `value` is forbidden. This rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so a validator does not check it.\",\"properties\":{\"profile\":{\"$ref\":\"#/$defs/Uri\",\"description\":\"The content profile, a URI: `https://hcp.example/spec/profiles/general-context/2.0` or `https://hcp.example/spec/profiles/vc-evidence/2.0` in HCP 2.0-draft-3, or a custom profile (HCP A.3).\"},\"value\":{\"type\":[\"string\",\"object\"],\"description\":\"The statement, under the General Context Profile: a string or a structured object (HCP 11.2).\"},\"language\":{\"type\":[\"string\",\"null\"],\"maxLength\":64,\"description\":\"The BCP 47 language tag of a string `value`, under the General Context Profile (HCP 11.2). Optional; may be null.\"},\"evidence\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Under the VC Evidence Profile, the index in `evidence` of the item whose credential is the content (HCP 4.2.2).\"}}},\"Uri\":{\"type\":\"string\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2048,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"description\":\"An absolute URI with no whitespace, as HCP writes every custom value at an extension point (HCP A.3).\"},\"EntrySubject\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"id\"],\"description\":\"The subject of an entry (HCP 4.2).\",\"properties\":{\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"A URI identifying the Context Subject of the HCP instance that holds the entry, possibly a pseudonym the provider issues (HCP 4.2).\"},\"relationship\":{\"type\":\"null\",\"description\":\"Reserved by HCP (HCP 4.2, 11.3); null where present.\"}}},\"Disclosure\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"ref\",\"version\",\"content\",\"assertion\",\"classification\",\"standing\",\"useUntil\"],\"description\":\"A disclosed copy of an entry (HCP 7.4). It names the entry by a grant-scoped `ref`, never by its `id`, and withholds the entry's `id`, `subject`, `schema` and the whole of `record` (status, provenance, relationships, conversion, metadata): those members describe the person's activity with other systems, which no grant authorizes a client to learn (HCP 7.4). What the client needs to judge the entry it receives in `standing`.\",\"properties\":{\"ref\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"A reference to the entry, opaque to the client, stable for one grant and one entry and different under every other grant, and never derivable into the entry's `id` (HCP 7.4). The client names the entry by it in get entry, revise and withdraw; under any other grant it fails with not authorized.\"},\"version\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The entry version disclosed: the stored `record.version` (HCP 7.4, 4.2).\"},\"content\":{\"$ref\":\"#/$defs/Content\",\"description\":\"The content, as stored for the version disclosed (HCP 7.4).\"},\"evidence\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/DisclosedEvidenceItem\"},\"description\":\"The evidence, as stored (so at most one item whose `role` is `content`, HCP 4.2.2), including each item's `verification`, except that a credential may be disclosed in derived form (HCP 7.4, 14.9). Absent or empty when none is disclosed. The one-`content`-item rule is stated here and not in the schema: the registry's Rust generator does not support `contains`, so a validator does not check it.\"},\"assertion\":{\"$ref\":\"#/$defs/Assertion\",\"description\":\"The assertion, as stored for the version disclosed, including `basis` and `permittedPurposes` (HCP 7.4).\"},\"classification\":{\"$ref\":\"#/$defs/Classification\",\"description\":\"Only the entry's categories the requesting grant covers, with its dimension and its `permittedPurposes` where present; its other categories are withheld (HCP 7.4).\"},\"standing\":{\"$ref\":\"#/$defs/Standing\",\"description\":\"What the client needs to judge the entry's standing (HCP 7.4, 3.8).\"},\"useUntil\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"The instant after which the client MUST NOT use the copy, or pass it on, without fetching it again (HCP 7.6). The provider sets it at disclosure: the earliest explicit time that applies (such as `assertion.validUntil`), else a heuristic of at least 1 hour; never more than 30 days after disclosure, 24 hours for an entry of High default sensitivity, or 1 hour where the client has no registered notification endpoint (HCP 7.6).\"},\"onwardSharing\":{\"const\":true,\"description\":\"Present, and true, only where the client may share from this entry under HCP 3.12: the detail of the grant that reaches the entry carries `onwardSharing` and every category of the entry has a default sensitivity of Low. Omitted otherwise (HCP 7.4).\"},\"relationships\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/$defs/DisclosedRelationship\"},\"description\":\"Only the relationships whose target is disclosed in the same response, with the target named by its `ref` (HCP 7.4, 4.2.3).\"},\"provenance\":{\"$ref\":\"#/$defs/DisclosedProvenance\",\"description\":\"Present only where the requesting grant includes the `provenance` action for a category of the entry (HCP 7.4.1).\"}},\"not\":{\"anyOf\":[{\"required\":[\"id\"]},{\"required\":[\"subject\"]},{\"required\":[\"record\"]},{\"required\":[\"schema\"]}]}},\"DisclosedProvenance\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"submittedBy\",\"source\",\"assertedAt\",\"recordedAt\"],\"description\":\"Provenance on request (HCP 7.4.1): names, never identifiers. It MUST NOT carry an identifier of a client, a Client Operator, a grant, a conversation or a document, nor `confirmedBy`.\",\"properties\":{\"submittedBy\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"name\",\"operator\"],\"description\":\"The names of the client that submitted the version disclosed and of its Client Operator.\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The client's name.\"},\"operator\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"The Client Operator's name.\"}}},\"source\":{\"type\":\"string\",\"enum\":[\"conversation\",\"document\",\"person-input\",\"integration\"],\"description\":\"The kind of origin the stored `source` records, not its value (HCP 7.4.1). HCP's own values, carried verbatim.\"},\"assertedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the assertion was made.\"},\"recordedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the provider recorded the version.\"}},\"not\":{\"anyOf\":[{\"required\":[\"id\"]},{\"required\":[\"confirmedBy\"]},{\"required\":[\"authorizedUnder\"]},{\"required\":[\"submittedByClient\"]}]}},\"DisclosedRelationship\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"type\",\"target\"],\"description\":\"A relationship as disclosed (HCP 7.4).\",\"properties\":{\"type\":{\"$ref\":\"#/$defs/RelationshipType\",\"description\":\"The kind of relationship.\"},\"target\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048,\"description\":\"The `ref` of the related entry, disclosed in the same response.\"}}},\"Standing\":{\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"assurance\",\"confirmed\"],\"description\":\"The standing of the disclosed version (HCP 7.4).\",\"properties\":{\"assurance\":{\"$ref\":\"#/$defs/Assurance\",\"description\":\"The stored `record.provenance.assertedBy.assurance`.\"},\"confirmed\":{\"type\":\"boolean\",\"description\":\"True where the most recent confirmation record on the version disclosed is `confirmed` (HCP 7.4, 3.8).\"}}},\"DisclosedEvidenceItem\":{\"description\":\"An evidence item as disclosed (HCP 7.4). An item carrying a derived credential adds `revealed`.\",\"allOf\":[{\"$ref\":\"#/$defs/EvidenceItem\"}],\"properties\":{\"revealed\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"maxLength\":2048},\"description\":\"The JSON Pointers into the stored credential of the claims a derived credential reveals (HCP 7.4, 14.9).\"}}}}}"

// Spec is the SPEC §7.2 policy for the request variant, taken from this
// specification's front matter. Pass it to trusttasks.ConsumeInbound — items 5b,
// 7 and 8 are per-specification and cannot be derived from the document alone,
// and item 2 needs the schema it carries.
var Spec = trusttasks.SpecPolicy{
	TypeURI:             TypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       PayloadSchemaJSON,
}

// ResponseSpec is the SPEC §7.2 policy for the success-response variant.
// IsRecipientRequired tracks the *issuer* party's requirement, because a response
// swaps the parties (§7.3 item 5).
var ResponseSpec = trusttasks.SpecPolicy{
	TypeURI:             ResponseTypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       ResponsePayloadSchemaJSON,
	MaxDocumentBytes:    524288,
}
